        const pkMenuButton=document.querySelector('#pk-menu'),pkNav=document.querySelector('#pk-nav');pkMenuButton.addEventListener('click',()=>{const open=pkMenuButton.getAttribute('aria-expanded')==='true';pkMenuButton.setAttribute('aria-expanded',String(!open));pkMenuButton.setAttribute('aria-label',open?'Buka menu':'Tutup menu');pkNav.classList.toggle('open',!open)});pkNav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{pkNav.classList.remove('open');pkMenuButton.setAttribute('aria-expanded','false');pkMenuButton.setAttribute('aria-label','Buka menu')}));
