        function pkRenderProjects(){const filterValues=[['year',pkYearFilter.value],['status',pkStatusFilter.value],['location',pkLocationFilter.value]],visible=pkProjects.filter(project=>filterValues.every(([key,value])=>!value||String(project[key]||'')===value));pkProjectList.replaceChildren();if(!visible.length){pkProjectList.append(pkSafe('p','pk-empty','Belum ada informasi pembangunan yang dapat ditampilkan.'));return}visible.forEach((project,index)=>{const row=document.createElement('article');row.className='pk-project';row.append(pkSafe('span','pk-project-number',String(index+1).padStart(2,'0')));const body=document.createElement('div'),meta=document.createElement('div');meta.className='pk-project-meta';[project.year,project.location,project.status].filter(Boolean).forEach(value=>meta.append(pkSafe('span','',String(value))));body.append(meta,pkSafe('h3','',project.title||'Kegiatan desa'),pkSafe('p','',project.summary||project.location||'Rincian belum tersedia.'));const actions=document.createElement('div');actions.className='pk-project-actions';actions.append(pkSafe('strong','',project.funding||'Anggaran belum tersedia'));const detail=document.createElement('button');detail.type='button';detail.className='pk-detail-button';detail.textContent='Rincian pekerjaan';const popover=pkProjectPopover(project);detail.addEventListener('click',()=>popover.classList.toggle('open'));row.append(body,actions);actions.append(detail);row.append(popover);pkProjectList.append(row)})}
