        const pkQuestions=[{key:'title',prompt:'Apa usulan yang ingin disampaikan?',required:true,type:'text'},{key:'location',prompt:'Di mana kebutuhan ini berada?',required:true,type:'text'},{key:'category',prompt:'Pilih bidang usulan.',required:false,type:'choice',options:['Infrastruktur','Lingkungan','Sosial','Ekonomi','Lainnya']},{key:'description',prompt:'Ceritakan usulan secara singkat.',required:true,type:'textarea'},{key:'name',prompt:'Nama (opsional).',required:false,type:'text'},{key:'contact',prompt:'Kontak yang bisa dihubungi (opsional).',required:false,type:'text'}];let pkAnswers={},pkStep=0;const pkChat=document.querySelector('#pk-chat'),pkMessages=document.querySelector('#pk-chat-messages'),pkControls=document.querySelector('#pk-chat-controls'),pkActions=document.querySelector('#pk-chat-actions'),pkError=document.querySelector('#pk-chat-error'),pkToggle=document.querySelector('#pk-chat-toggle');
        function pkSay(text,user=false){pkMessages.append(pkSafe('div',`pk-chat-message${user?' is-user':''}`,text));pkChat.querySelector('.pk-chat-body').scrollTop=pkChat.querySelector('.pk-chat-body').scrollHeight}function pkAction(label,handler,primary=false){const button=pkSafe('button',primary?'primary':'',label);button.type='button';button.addEventListener('click',handler);return button}function pkCloseChat(reset=true){pkChat.classList.remove('open');pkChat.setAttribute('aria-hidden','true');pkToggle.setAttribute('aria-expanded','false');if(reset){pkAnswers={};pkStep=0;pkMessages.replaceChildren();pkControls.replaceChildren();pkActions.replaceChildren();pkError.textContent=''}}
        function pkRenderQuestion(){pkControls.replaceChildren();pkActions.replaceChildren();pkError.textContent='';if(pkStep>=pkQuestions.length){pkSay('Periksa kembali usulan sebelum dikirim.');pkSay(`${pkAnswers.title}\n${pkAnswers.location}\n${pkAnswers.description}`);pkActions.append(pkAction('Batal',()=>pkCloseChat()),pkAction('Kirim usulan',pkSubmitProposal,true));return}const question=pkQuestions[pkStep];pkSay(question.prompt);pkControls.append(pkSafe('div','pk-chat-prompt',`${pkStep+1} dari ${pkQuestions.length}`));if(question.type==='choice'){const options=document.createElement('div');options.className='pk-chat-options';question.options.forEach(option=>options.append(pkAction(option,()=>{pkAnswers[question.key]=option;pkSay(option,true);pkStep++;pkRenderQuestion()})));pkControls.append(options)}else{const input=document.createElement(question.type==='textarea'?'textarea':'input');input.className='pk-chat-input';input.placeholder=question.key==='title'?'Judul usulan':question.key==='location'?'Lokasi':question.key==='description'?'Uraian singkat':question.key==='name'?'Nama':'Kontak';input.setAttribute('aria-label',input.placeholder);input.maxLength=question.key==='description'?3000:160;if(question.type==='textarea')input.rows=3;pkControls.append(input)}pkActions.append(pkAction('Batal',()=>pkCloseChat()));if(!question.required)pkActions.append(pkAction('Lewati',()=>{pkAnswers[question.key]='';pkStep++;pkRenderQuestion()}));pkActions.append(pkAction(pkStep===pkQuestions.length-1?'Tinjau':'Lanjut',()=>{const input=pkControls.querySelector('input,textarea'),value=input?.value.trim()||'';if(question.required&&!value){pkError.textContent='Bagian ini perlu diisi.';return}pkAnswers[question.key]=value;if(value)pkSay(value,true);pkStep++;pkRenderQuestion()},true))}
        async function pkSubmitProposal(){pkError.textContent='';const submit=pkActions.querySelector('.primary');submit.disabled=true;try{const response=await fetch('/api/desa/pikatan/proposals',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({...pkAnswers,website:''})});const result=response.status===204?{}:await response.json();if(!response.ok)throw new Error(result.message||'Usulan belum berhasil dikirim.');pkMessages.replaceChildren();pkControls.replaceChildren();pkActions.replaceChildren();pkSay(result.message||'Usulan berhasil dikirim.');pkActions.append(pkAction('Selesai',()=>pkCloseChat(),true))}catch(exception){pkError.textContent=exception.message;submit.disabled=false}}
        pkToggle.addEventListener('click',()=>{const open=!pkChat.classList.contains('open');pkChat.classList.toggle('open',open);pkChat.setAttribute('aria-hidden',String(!open));pkToggle.setAttribute('aria-expanded',String(open));if(open&&!pkMessages.childElementCount)pkRenderQuestion()});document.querySelector('#pk-chat-close').addEventListener('click',()=>pkCloseChat(false));
    </script>
    @include('desa.partials.managed-content')
    @include('desa.partials.responsive')
</body>
</html>
